);

    logic ex_mem_hit_a;
    logic ex_mem_hit_b;
    logic mem_wb_hit_a;
    logic mem_wb_hit_b;

    always_comb begin
        ex_mem_hit_a = ex_mem_valid && ex_mem_reg_write && (ex_mem_rd != 5'd0) &&
                       !ex_mem_is_load && (ex_mem_rd == id_ex_rs1_addr);
        ex_mem_hit_b = ex_mem_valid && ex_mem_reg_write && (ex_mem_rd != 5'd0) &&
