    always_comb begin
        rs1_fwd = id_ex_rs1_data;
        if (fwd_a == 2'b01)
            rs1_fwd = ex_mem_alu_result;
        else if (fwd_a == 2'b10)
            rs1_fwd = mem_wb_wdata;

        rs2_fwd = id_ex_rs2_data;
        if (fwd_b == 2'b01)
            rs2_fwd = ex_mem_alu_result;
        else if (fwd_b == 2'b10)
            rs2_fwd = mem_wb_wdata;
    end

